// Uses real PreviewHtml fixtures generated by Gradle; no private diagrams or IDE UI needed.
const assert = require('node:assert/strict');
const path = require('node:path');
const fs = require('node:fs');
const { pathToFileURL } = require('node:url');
const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch({ headless: true, ...(process.env.DBML_BROWSER_CHANNEL ? { channel: process.env.DBML_BROWSER_CHANNEL } : {}) });
  const directory = path.resolve(__dirname, '../../../build/reports/free-canvas');
  try {
    const page = await browser.newPage({ viewport: { width: 1600, height: 1100 }, deviceScaleFactor: 1.5 });
    const errors = [];
    page.on('pageerror', error => errors.push(error.message));
    const near = (a, b, message) => assert.ok(Math.abs(a - b) < .02, `${message}: ${a} vs ${b}`);
    const camera = () => page.evaluate(() => ({ scale, tx, ty, gridEnabled, snapEnabled }));
    const positions = () => page.locator('g[data-table]').evaluateAll(gs => Object.fromEntries(gs.map(g => [g.dataset.table, { x: +g.dataset.x, y: +g.dataset.y }])));
    async function center(selector) {
      const box = await page.locator(selector).boundingBox();
      assert.ok(box, selector);
      return { x: box.x + box.width / 2, y: box.y + box.height / 2 };
    }
    async function dragAt(start, dx, dy, button = 'left') {
      await page.mouse.move(start.x, start.y);
      await page.mouse.down({ button });
      await page.mouse.move(start.x + dx, start.y + dy, { steps: 16 });
      await page.mouse.up({ button });
    }
    async function assertEndpoints() {
      assert.deepEqual(await page.evaluate(() => {
        const failures = [];
        document.querySelectorAll('.relation-route').forEach(r => {
          for (const [end, index] of [['from', 0], ['to', r.querySelector('.relation').points.numberOfItems - 1]]) {
            const p = r.querySelector('.relation').points.getItem(index), expected = endpointPoint(r, end, r.dataset[end + 'Side']);
            if (Math.abs(p.x - expected.x) > .01 || Math.abs(p.y - expected.y) > .01) failures.push(r.dataset.relationId + ':' + end);
          }
        });
        return failures;
      }), [], 'Arrows must remain anchored to the actual FK/PK columns');
    }
    for (const theme of ['light', 'dark']) {
      await page.goto(pathToFileURL(path.join(directory, `preview-${theme}.html`)).href);
      assert.equal(await page.locator('#grid-toggle').getAttribute('aria-pressed'), 'true');
      assert.equal(await page.locator('#snap-toggle').getAttribute('aria-pressed'), 'false');
      assert.equal((await positions()).users.x, -700);
      const grid = await page.evaluate(() => {
        const style = getComputedStyle(v), gap = parseFloat(style.backgroundSize);
        const [x, y] = style.backgroundPosition.split(' ').map(parseFloat);
        return { x: (x + gap / 2 - tx) % gap, y: (y + gap / 2 - ty) % gap };
      });
      near(grid.x, 0, 'Grid aligns with world x=0'); near(grid.y, 0, 'Grid aligns with world y=0');
      await assertEndpoints();
      await page.evaluate(() => fit(false));
      await page.screenshot({ path: path.join(directory, `free-canvas-${theme}.png`) });
    }
    // Space-drag must pan even when it starts directly on a table.
    let before = await positions(), view = await camera();
    await page.keyboard.down('Space');
    await dragAt(await center('g[data-table="users"] .head'), 160, 100);
    await page.keyboard.up('Space');
    assert.deepEqual(await positions(), before);
    let moved = await camera(); near(moved.tx - view.tx, 160, 'Space-pan x'); near(moved.ty - view.ty, 100, 'Space-pan y');
    // The same gesture over a group header must not move its contents.
    view = await camera();
    await page.keyboard.down('Space');
    await dragAt(await center('g[data-table-group="Accounts"] .table-group-label'), 25, 30);
    await page.keyboard.up('Space');
    assert.deepEqual(await positions(), before);
    near((await camera()).tx - view.tx, 25, 'Space-pan over frame');
    // Middle-button pan has priority over relationship hit areas.
    const linePoint = await page.locator('.relation-hit').first().evaluate(line => {
      const p = line.points.getItem(0); return new DOMPoint(p.x, p.y).matrixTransform(line.getScreenCTM()).toJSON();
    });
    view = await camera(); await dragAt(linePoint, -40, 20, 'middle');
    assert.deepEqual(await positions(), before);
    near((await camera()).tx - view.tx, -40, 'Middle-button pan');
    // Zoom must leave the same world point under the cursor.
    const cursor = { x: 900, y: 400 };
    view = await camera();
    const world = { x: (cursor.x - view.tx) / view.scale, y: (cursor.y - view.ty) / view.scale };
    await page.mouse.move(cursor.x, cursor.y);
    await page.keyboard.down('Control'); await page.mouse.wheel(0, -140); await page.keyboard.up('Control');
    await page.waitForFunction(previous => scale > previous, view.scale);
    moved = await camera(); near((cursor.x - moved.tx) / moved.scale, world.x, 'Cursor anchored zoom x'); near((cursor.y - moved.ty) / moved.scale, world.y, 'Cursor anchored zoom y');
    // Ordinary wheel pans rather than silently doing nothing.
    view = await camera(); await page.mouse.wheel(40, 60);
    await page.waitForFunction(previous => ty < previous, view.ty);
    moved = await camera(); near(moved.scale, view.scale, 'Wheel preserves zoom');
    assert.ok(moved.tx < view.tx && moved.ty < view.ty, 'Wheel must pan both axes');
    near((moved.tx - view.tx) / (moved.ty - view.ty), 2 / 3, 'Wheel direction (browser may normalize by device scale)');
    // Put the scene back inside the viewport before actual object dragging.
    await page.evaluate(() => { scale = .7; tx = 850; ty = 600; apply(); window.savedPayloads = []; });
    // Repeated pointer events schedule only one expensive routing pass per animation frame.
    await page.evaluate(() => {
      window.originalFlush = flushRoutes; window.flushCount = 0;
      flushRoutes = function () { window.flushCount++; window.originalFlush(); };
      for (let i = 0; i < 100; i++) queueRoutes();
    });
    await page.waitForFunction(() => window.flushCount > 0);
    assert.equal(await page.evaluate(() => window.flushCount), 1);
    await page.evaluate(() => { flushRoutes = window.originalFlush; });
    before = await positions(); view = await camera();
    await dragAt(await center('g[data-table-group="Accounts"] .table-group-label'), -140, -84);
    moved = await positions();
    for (const id of ['users', 'orders']) { near(moved[id].x - before[id].x, -200, 'Group member dx'); near(moved[id].y - before[id].y, -120, 'Group member dy'); }
    assert.deepEqual(moved.products, before.products); assert.deepEqual(moved.audit, before.audit);
    const payloads = await page.evaluate(() => window.savedPayloads);
    assert.equal(payloads.length, 1, 'Group move must be one atomic update, not a series of per-table reloads');
    assert.ok(payloads[0].startsWith('B\t'));
    const batch = JSON.parse(decodeURIComponent(payloads[0].slice(2)));
    assert.equal(batch.tables.length, 2); assert.equal(batch.routes.length, 1);
    assert.ok(batch.tables.every(t => t.x < 0 && t.y < 0));
    near(batch.view.scale, view.scale, 'Batch camera scale');
    fs.writeFileSync(path.join(directory, 'group-move-payload.txt'), payloads[0]);
    await assertEndpoints();
    // A second group drag must not accumulate SVG transform errors.
    await dragAt(await center('g[data-table-group="Accounts"] .table-group-handle'), 140, 84);
    moved = await positions();
    for (const id of ['users', 'orders']) { near(moved[id].x, before[id].x, 'Repeated group drag x'); near(moved[id].y, before[id].y, 'Repeated group drag y'); }
    // Move an individual already-negative table farther left/up; it must not clamp to 48.
    await dragAt(await center('g[data-table="users"] .head'), -70, -42);
    moved = await positions(); near(moved.users.x, before.users.x - 100, 'Negative individual drag x'); near(moved.users.y, before.users.y - 60, 'Negative individual drag y');
    assert.deepEqual(moved.orders, before.orders);
    await assertEndpoints();
    // Optional snapping applies in world coordinates, not screen pixels.
    await page.locator('#snap-toggle').click();
    await dragAt(await center('g[data-table="users"] .head'), 31, 19);
    moved = await positions(); near(moved.users.x / 24, Math.round(moved.users.x / 24), 'Snap x'); near(moved.users.y / 24, Math.round(moved.users.y / 24), 'Snap y');
    await page.locator('#grid-toggle').click();
    assert.equal(await page.locator('#grid-toggle').getAttribute('aria-pressed'), 'false');
    assert.equal(await page.locator('#viewport').evaluate(e => getComputedStyle(e).backgroundImage), 'none');
    // Fit uses actual objects after shrink, not the monotonically grown SVG dimensions.
    const expected = await page.evaluate(() => contentBounds());
    await page.evaluate(() => fit()); view = await camera();
    near((expected.x + expected.w / 2) * view.scale + view.tx, 800, 'Fit world center x');
    near((expected.y + expected.h / 2) * view.scale + view.ty, 550, 'Fit world center y');
    const sceneBeforeResize = await camera();
    await page.setViewportSize({ width: 1800, height: 1200 });
    await page.waitForFunction(previous => tx > previous + 50, sceneBeforeResize.tx);
    moved = await camera(); near(moved.scale, sceneBeforeResize.scale, 'Resize preserves zoom');
    near(moved.tx - sceneBeforeResize.tx, 100, 'Resize preserves world center');
    // World extents must not become a gigantic raster viewport. Far-positive objects stay hittable.
    const rootSize = await page.locator('svg').evaluate(s => [s.getAttribute('width'), s.getAttribute('height')]);
    await page.evaluate(() => {
      setTablePosition(tableGroup('users'), 100000, 100000); updateTableGroups(); flushRoutes();
      scale = 1; tx = innerWidth / 2 - 100180; ty = innerHeight / 2 - 100019; apply();
    });
    assert.deepEqual(await page.locator('svg').evaluate(s => [s.getAttribute('width'), s.getAttribute('height')]), rootSize);
    await dragAt(await center('g[data-table="users"] .head'), 48, 24);
    moved = await positions(); near(moved.users.x, 100056, 'Far-positive object remains interactive with snap');
    near(moved.users.y, 100032, 'Far-positive y');
    await page.goto(pathToFileURL(path.join(directory, 'preview-restored.html')).href);
    assert.deepEqual(await camera(), { scale: .6, tx: 1000, ty: 700, gridEnabled: false, snapEnabled: true });
    assert.equal((await positions()).users.x, -700);
    assert.equal(await page.locator('#grid-toggle').getAttribute('aria-pressed'), 'false');
    // Loss of focus must not leave a stuck Space/panning mode.
    await page.keyboard.down('Space'); await page.evaluate(() => window.dispatchEvent(new Event('blur'))); await page.keyboard.up('Space');
    assert.equal(await page.evaluate(() => spaceDown), false);
    assert.deepEqual(errors, []);
    console.log('Free canvas passed: negative coordinates, table/group drag, atomic persistence, Space/middle/wheel pan, cursor zoom, grid/snap, Fit, resize, restored camera and arrow anchors.');
  } finally { await browser.close(); }
})().catch(error => { console.error(error); process.exitCode = 1; });
